use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/inverse-seed-scale176";
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-07-inverse-seed-scale176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){
 let pins=read(format!("{R}/pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let audit=read(format!("{R}/source-audit.json"));assert_eq!(audit["production_sources_checked"],176);let mut recovered=fs::read_to_string(format!("{R}/candidate.rs")).unwrap();recovered=recovered.strip_suffix(audit["probe_suffix"].as_str().unwrap()).unwrap().to_owned();for c in audit["changes"].as_array().unwrap().iter().rev(){let old=c[0].as_str().unwrap();let new=c[1].as_str().unwrap();assert_eq!(recovered.matches(new).count(),1);recovered=recovered.replace(new,old);}assert_eq!(recovered,fs::read_to_string("/home/ubuntu/src/zk-tools/zopro/crates/zopro-bn254/src/inverse.rs").unwrap());
 let mut receipts=Vec::new();for n in ["build-new-seed-scale-qualification","qualify-new-seed-scale-invariant"]{let dir=format!("{R}/runs/{n}");let exit=read(format!("{dir}/exit.json"));assert_eq!(exit["returncode"],0);assert_eq!(exit["success"],true);for stream in ["stdout","stderr"]{assert_eq!(exit[format!("{stream}_sha256")],hash(format!("{dir}/{stream}.log")));}let command=read(format!("{dir}/command.json"));receipts.push(json!({"name":n,"command":command,"exit":exit}));}
 let command=&receipts[0]["command"]["argv"];for flag in ["lto=fat","opt-level=3","target-cpu=native","codegen-units=1","zopro_gcd_balanced_runs","zopro_inverse_seed_observe","overflow-checks=yes","debug-assertions=yes"]{assert!(command.as_array().unwrap().iter().any(|a|a.as_str()==Some(flag)));}
 let q=read(format!("{R}/qualification.json"));assert_eq!(q["passed"],true);assert_eq!(q["new_proofs"],0);assert_eq!(q["new_timings"],0);let fields=q["fields"].as_array().unwrap();assert_eq!(fields.len(),2);let mut complete=0;let mut finish=0;for f in fields{assert_eq!(f["complete_inverse_outputs"],7168);assert_eq!(f["input_rows"],6657);assert_eq!(f["changing_chain_steps"],512);assert_eq!(f["crafted_finish_states"],3324);assert_eq!(f["inverse_branches_zero_normal_b1_outer"],json!([1,6659,509,0]));assert_eq!(f["crafted_finish_branches"],json!([0,3321,3,0]));assert_eq!(f["seed_identity"],true);assert_eq!(f["early_correction_identity"],true);complete+=f["complete_inverse_outputs"].as_u64().unwrap();finish+=f["crafted_finish_states"].as_u64().unwrap();}
 let result=json!({"passed":true,"review_scope":"Receipt/pin/source recovery/output count and branch coverage review; successful arithmetic qualification not rerun","pins":pins.as_object().unwrap().len(),"production_sources":176,"complete_inverse_outputs":complete,"crafted_finish_states":finish,"ordinary_finish_total":13318,"early_b1_total":1018,"outer_GCD_exit_observed":false,"outer_correction":"Same corrective multiplication as exercised b==1 path; not an executed outer-path test","prototype_sha256":hash(format!("{R}/qualify")),"successful_commands":2,"new_proofs":0,"new_timings":0,"goal_active":true,"targets_achieved":0,"candidate_selected_for_performance_protocol_only":true});
 let rp=format!("{R}/review.json");assert!(!Path::new(&rp).exists());fs::write(&rp,serde_json::to_vec_pretty(&result).unwrap()).unwrap();
 let ad=PathBuf::from(D).join("artifacts");assert!(!Path::new(D).exists());fs::create_dir_all(&ad).unwrap();
 let mut members=BTreeMap::new();for n in ["design.md","candidate.rs","prepare.rs","qualify.rs","source-audit.json","qualification.json","pins.json","plan.json","review-publish.rs","review.json"]{let source=format!("{R}/{n}");let target=ad.join(n);fs::copy(&source,&target).unwrap();assert_eq!(fs::read(&source).unwrap(),fs::read(&target).unwrap());members.insert(format!("artifacts/{n}"),hash(&target));}
 for n in ["build-new-seed-scale-qualification","qualify-new-seed-scale-invariant"]{for leaf in ["command.json","exit.json","stdout.log","stderr.log","tests.json"]{let source=format!("{R}/runs/{n}/{leaf}");let rel=format!("artifacts/runs/{n}/{leaf}");let target=Path::new(D).join(&rel);fs::create_dir_all(target.parent().unwrap()).unwrap();fs::copy(&source,&target).unwrap();assert_eq!(fs::read(source).unwrap(),fs::read(&target).unwrap());members.insert(rel,hash(&target));}}
 fs::copy(format!("{R}/README.md"),Path::new(D).join("README.md")).unwrap();members.insert("README.md".into(),hash(Path::new(D).join("README.md")));
 let publication=json!({"members_sha256":members,"exact_copies_checked":true,"excluded":"Compiled binaries/libraries, private keys/inputs/proofs, external source bodies; no external implementation executed","new_field_suite_runs":0,"new_SDK_requests":0,"new_Gnark_exports":0});fs::write(ad.join("publication.json"),serde_json::to_vec_pretty(&publication).unwrap()).unwrap();members.insert("artifacts/publication.json".into(),hash(ad.join("publication.json")));
 let checks=members.iter().map(|(n,h)|format!("{h}  {n}\n")).collect::<String>();fs::write(Path::new(D).join("SHA256SUMS"),checks).unwrap();println!("PASS {} pins,2 receipts,14336 complete inverse outputs/6648 crafted finishes; {} exact public members; no timing/adoption",pins.as_object().unwrap().len(),members.len());
}
